#!/usr/bin/env python3
"""Patch a CI-generated Flutter android build.gradle(.kts) with release
signing, R8 minification and resource shrinking.

Usage: patch_android_signing.py <android/app directory>

The DreamTX repo does not commit the android platform folder; it is
regenerated by `flutter create` on every CI run. This script runs right
after it and injects into `buildTypes.release`:

  * a `signingConfigs.release` entry reading the keystore from
    app/android/app/release-keystore.jks and credentials from env vars
    (KEYSTORE_PASSWORD / KEY_ALIAS / KEY_PASSWORD), with a conditional
    fallback to debug signing when the env vars are absent (fork PRs) so
    those builds keep working;
  * `isMinifyEnabled = true` + `isShrinkResources = true` + the optimize
    proguard file — R8 tree-shakes and obfuscates the Java/Kotlin side
    (plugins included) and the resource shrinker strips what no code
    references anymore. The deck engine is native code (already
    `opt-level=z` + stripped in the Rust profile); this takes the
    remaining dex/resource slack out of the ~64MB universal APK;
  * `proguard-rules.pro` next to it, pinning the keep rules that keep the
    app honest: DreamTX's own MainActivity (the `dreamtx/saf` and
    `dreamtx/media` channels — reflected by NAME from Dart), the Flutter
    embedding, and the plugin classes the plugins reflect into
    (file_picker's document browser, image_picker's camera/exif path,
    share_plus's MethodChannel task, path_provider_android's channel).

Exits non-zero if the expected anchor lines cannot be found - we would
rather fail loudly than silently ship a debug-signed release APK.
"""
import os
import re
import sys

PROGUARD_RULES = """# DreamTX keep rules — R8 shrinks everything else.
#
# The app is a thin Flutter/Dart shell over a native Rust engine: the dex
# is plugins + embedding + the small MainActivity that carries the
# `dreamtx/saf` and `dreamtx/media` method channels. What must survive
# shrinking is exactly what is reached BY NAME (platform channels,
# reflected plugin classes) instead of by code graph.

# The app's own host: MainActivity registers both channels; the class and
# its methods are instantiated by the embedding, not by Dart's code graph.
-keep class com.dreamtx.dreamtx.** { *; }

# The Flutter embedding (JNI + reflection across the whole surface).
-keep class io.flutter.** { *; }
-keep class io.flutter.plugin.** { *; }
-dontwarn io.flutter.**

# Platform plugins the app bundles — each reaches Java by reflection
# (channel names, registered plugin classes, Exif/URI internals):
-keep class com.mr.flutter.plugins.filepicker.** { *; }
-keep class com.jeremyflores.flutter.plugins.filepicker.** { *; }
-keep class io.flutter.plugins.imagepicker.** { *; }
-keep class dev.fluttercommunity.plus.** { *; }
-keep class io.flutter.plugins.pathprovider.** { *; }
-dontwarn com.mr.flutter.plugins.filepicker.**
-dontwarn io.flutter.plugins.imagepicker.**

# Kotlin metadata + annotations the plugins read at runtime.
-keepattributes *Annotation*, InnerClasses, Signature
-keepclassmembers class * { @androidx.annotation.* <fields>; }
"""


def main() -> int:
    if len(sys.argv) != 2:
        print("usage: patch_android_signing.py <android/app dir>", file=sys.stderr)
        return 2
    app_dir = sys.argv[1]

    gradle = None
    for name in ("build.gradle.kts", "build.gradle"):
        p = os.path.join(app_dir, name)
        if os.path.exists(p):
            gradle = p
            break
    if gradle is None:
        print("patch_android_signing: no build.gradle(.kts) found in " + app_dir,
              file=sys.stderr)
        return 1

    src = open(gradle).read()

    # ---- the proguard keep rules (before the gradle patch; idempotent) ----
    proguard = os.path.join(app_dir, "proguard-rules.pro")
    if not (os.path.exists(proguard) and open(proguard).read() == PROGUARD_RULES):
        open(proguard, "w").write(PROGUARD_RULES)
        print("patch_android_signing: wrote " + proguard + " (keep rules)")

    already_patched = "release-keystore.jks" in src
    if already_patched and "isMinifyEnabled" in src:
        print(f"patch_android_signing: {os.path.basename(gradle)} already patched")
        return 0

    kotlin = gradle.endswith(".kts")

    if kotlin:
        cfg_block = (
            "    signingConfigs {\n"
            "        create(\"release\") {\n"
            "            if (System.getenv(\"KEYSTORE_PASSWORD\") != null) {\n"
            "                storeFile = file(\"release-keystore.jks\")\n"
            "                storePassword = System.getenv(\"KEYSTORE_PASSWORD\")\n"
            "                keyAlias = System.getenv(\"KEY_ALIAS\")\n"
            "                keyPassword = System.getenv(\"KEY_PASSWORD\")\n"
            "            }\n"
            "        }\n"
            "    }\n"
        )
        pattern = re.compile(r'signingConfig\s*=\s*signingConfigs\.getByName\("debug"\)')
        replacement = (
            'signingConfig = if (System.getenv("KEYSTORE_PASSWORD") != null) '
            'signingConfigs.getByName("release") '
            'else signingConfigs.getByName("debug")\n'
            "            // R8 + resource shrinking: tree-shake the dex and the\n"
            "            // resources (keep rules in proguard-rules.pro — the\n"
            "            // channels and reflected plugin classes survive).\n"
            "            isMinifyEnabled = true\n"
            "            isShrinkResources = true\n"
            "            proguardFiles(\n"
            "                getDefaultProguardFile(\"proguard-android-optimize.txt\"),\n"
            "                \"proguard-rules.pro\"\n"
            "            )"
        )
    else:
        cfg_block = (
            "    signingConfigs {\n"
            "        release {\n"
            "            if (System.getenv(\"KEYSTORE_PASSWORD\") != null) {\n"
            "                storeFile file(\"release-keystore.jks\")\n"
            "                storePassword System.getenv(\"KEYSTORE_PASSWORD\")\n"
            "                keyAlias System.getenv(\"KEY_ALIAS\")\n"
            "                keyPassword System.getenv(\"KEY_PASSWORD\")\n"
            "            }\n"
            "        }\n"
            "    }\n"
        )
        pattern = re.compile(r"signingConfig\s*=?\s*signingConfigs\.debug")
        replacement = (
            'signingConfig = (System.getenv("KEYSTORE_PASSWORD") != null ? '
            "signingConfigs.release : signingConfigs.debug)\n"
            "            // R8 + resource shrinking: tree-shake the dex and the\n"
            "            // resources (keep rules in proguard-rules.pro — the\n"
            "            // channels and reflected plugin classes survive).\n"
            "            minifyEnabled true\n"
            "            shrinkResources true\n"
            "            proguardFiles getDefaultProguardFile('proguard-android-optimize.txt'), 'proguard-rules.pro'"
        )

    if not pattern.search(src):
        print(f"patch_android_signing: signing anchor not found in {gradle}",
              file=sys.stderr)
        return 1
    if "buildTypes {" not in src:
        print(f"patch_android_signing: buildTypes block not found in {gradle}",
              file=sys.stderr)
        return 1

    # Replace the debug signingConfig assignment inside buildTypes.release
    # (carrying the minify block with it — same block, one injection point).
    src = pattern.sub(replacement, src, count=1)

    # Insert the signingConfigs block just above the buildTypes block,
    # preserving the original indentation of the buildTypes line.
    src = re.sub(r"([ \t]*)buildTypes \{",
                 lambda m: cfg_block + m.group(0),
                 src, count=1)

    open(gradle, "w").write(src)
    print(f"patch_android_signing: patched {gradle} "
          f"({'kotlin' if kotlin else 'groovy'} dsl) with release signing + "
          f"R8 minify + resource shrinking")
    return 0


if __name__ == "__main__":
    sys.exit(main())
